27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    public String getHouseholdId() {
118	        return this.householdId;
119	    }
120	
121	    public void setHouseholdId(String householdId) {
122	        this.householdId = householdId;
123	    }
124	
125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
135	     */
136	    @Transient
137	    public String getDisplayName() {
138	        return this.getLastName() + ", " + this.getFirstName();
139	    }
140	
141	    /**
142	     * The owner's initials: the upper-cased first letters of firstName and
143	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
144	     */
145	    @Transient
146	    public String getInitials() {
147	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
148	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
149	    }
150	
151	    /**
152	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
153	     * YY is the last two digits of the registration date's year
154	     * (e.g. {@code "TOW-SMI-0007-M26"}). Derived from the owner's own fields; null when
155	     * either the customer code or registration date is absent.
156	     */
157	    @Transient
158	    public String getMembershipNumber() {
159	        if (this.customerCode == null || this.registrationDate == null) {
160	            return null;
161	        }
162	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
163	    }
164	
165	    /**
166	     * The owner's membership tier: {@code "SILVER"} when the owner has no namesakes
167	     * (namesakeCount is 0) and an email address is present, otherwise {@code "BRONZE"}.
168	     * Derived from the owner's own fields.
169	     */
170	    @Transient
171	    public String getMembershipTier() {
172	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
173	        boolean hasEmail = this.email != null && !this.email.isBlank();
174	        return (unique && hasEmail) ? "SILVER" : "BRONZE";
175	    }
176	
177	    /**
178	     * Fixed city-to-region lookup table. Any city not listed derives locality
179	     * {@code "UNKNOWN"}.
180	     */
181	    private static final Map<String, String> CITY_REGION = Map.of(
182	        "Sydney", "NSW",
183	        "Melbourne", "VIC",
184	        "Brisbane", "QLD");
185	
186	    /**
187	     * The owner's locality: the canonical region derived from the city using the
188	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
189	     * {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the city is not in the table.
190	     * Derived from the owner's own fields.
191	     */
192	    @Transient
193	    public String getLocality() {
194	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
195	    }
196	
197	    protected Set<Pet> getPetsInternal() {
198	        if (this.pets == null) {
199	            this.pets = new HashSet<>();
200	        }
201	        return this.pets;
202	    }
203	
204	    protected void setPetsInternal(Set<Pet> pets) {
205	        this.pets = pets;
206	    }
207	
208	    public List<Pet> getPets() {
209	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
210	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
211	        return Collections.unmodifiableList(sortedPets);
212	    }
213	
214	    public void setPets(List<Pet> pets) {
215	        this.pets = new HashSet<>(pets);
216	    }
217	
218	    public void addPet(Pet pet) {
219	        getPetsInternal().add(pet);
220	        pet.setOwner(this);
221	    }
222	
223	    /**
224	     * Return the Pet with the given name, or null if none found for this Owner.
225	     *
226	     * @param name to test
227	     * @return true if pet name is already in use
228	     */
229	    public Pet getPet(String name) {
230	        return getPet(name, false);
231	    }
232	
233	    /**
234	     * Return the Pet with the given name, or null if none found for this Owner.
235	     *
236	     * @param name to test
237	     * @return true if pet name is already in use
238	     */
239	    public Pet getPet(String name, boolean ignoreNew) {
240	        name = name.toLowerCase();
241	        for (Pet pet : getPetsInternal()) {
242	            if (!ignoreNew || !pet.isNew()) {
243	                String compName = pet.getName();
244	                compName = compName.toLowerCase();
245	                if (compName.equals(name)) {
246	                    return pet;
247	                }
248	            }
249	        }
250	        return null;
251	    }
252	
253	    public Pet getPet(Integer petId) {
254	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
255	    }
256	
257	    @Override
258	    public String toString() {
259	        return new ToStringCreator(this)
260	
261	            .append("id", this.getId())
262	            .append("new", this.isNew())
263	            .append("lastName", this.getLastName())
264	            .append("firstName", this.getFirstName())
265	            .append("address", this.address)
266	            .append("city", this.city)
267	            .append("telephone", this.telephone)
268	            .append("email", this.email)
269	            .toString();
270	    }
271	}
